    "dailymed-lovenox": { label: "DailyMed Lovenox enoxaparin prescribing information and partial-reversal guidance", url: "https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=5017a927-2a24-4f27-89f9-27c805bf7d59&type=display" },
    "dailymed-octreotide": { label: "DailyMed octreotide acetate injection prescribing information", url: "https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=387d7f8d-9762-4f6b-99e1-bdc50b8a1633" },
    "pubmed-octreotide-2025": { label: "2025 systematic review of octreotide for sulfonylurea poisoning", url: "https://pubmed.ncbi.nlm.nih.gov/39821850/" },
